#!/usr/bin/env node
// Build the versioned browser bundle that other applications vendor:
//
//   core/*.js      the portable semantic core, byte-identical to tools/core/
//   catalog.json   the runtime catalog (schema, vocabulary, grammar, kernel, cards, dimensions)
//   catalog.js     the same catalog as an ES module, for importers without JSON modules
//   package.json   marks the bundle as ES modules for Node
//   LICENSES/      MIT for the code, CC BY-NC-SA 4.0 for the catalog content
//   README.md      what this is and how to verify it
//   MANIFEST.json  versions, source commit and the SHA-256 of every other file
//
// Output is deterministic: bundling the same commit twice gives identical files.
//
//   node tools/bundle.js [--out DIR] [--allow-dirty]
import { execFileSync } from 'node:child_process';
import { createHash } from 'node:crypto';
import { mkdirSync, readdirSync, readFileSync, rmSync, writeFileSync } from 'node:fs';
import { dirname, join, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';
import { parseArgs } from 'node:util';
import { RUNTIME_VERSION } from './core/bootstrap.js';
import { COMPOSER_VERSION } from './core/composer.js';
import { loadCatalog } from './lib/catalog.js';
import { readRepoFile, readRepoJSON, repoRoot } from './lib/vocabulary.js';

const root = fileURLToPath(repoRoot);
const version = readRepoJSON('package.json').version;

const { values } = parseArgs({
  options: {
    out: { type: 'string', default: join(root, 'dist', `mwer-browser-${version}`) },
    'allow-dirty': { type: 'boolean', default: false },
  },
});

const git = args => execFileSync('git', args, { cwd: root, encoding: 'utf8' }).trim();
const dirty = git(['status', '--porcelain']) !== '';
if (dirty && !values['allow-dirty']) {
  console.error('The working tree has uncommitted changes. Commit first, or pass --allow-dirty for a local test bundle.');
  process.exit(1);
}
const commit = dirty ? null : git(['rev-parse', 'HEAD']);

const files = new Map();
const coreDir = new URL('tools/core/', repoRoot);
for (const name of readdirSync(coreDir).filter(n => n.endsWith('.js')).sort()) {
  files.set(`core/${name}`, readFileSync(new URL(name, coreDir)));
}
const catalog = JSON.stringify(loadCatalog(), null, 2);
files.set('catalog.json', `${catalog}\n`);
files.set('catalog.js', `// Generated by mindwright-experience-runtime tools/bundle.js. Do not edit.\nexport default ${catalog};\n`);
// Marks the bundle as ES modules for Node consumers that have no package.json of their own.
files.set('package.json', `${JSON.stringify({ name: 'mwer-browser', version, private: true, type: 'module' }, null, 2)}\n`);
files.set('LICENSES/MIT.txt', readRepoFile('LICENSE-CODE'));
files.set('LICENSES/CC-BY-NC-SA-4.0.txt', readRepoFile('LICENSE'));
files.set('README.md', [
  `# MWER browser bundle ${version}`,
  '',
  `Runtime ${RUNTIME_VERSION}, composer ${COMPOSER_VERSION}, built from ${commit ? `commit ${commit}` : 'an uncommitted working tree (not for release)'}.`,
  '',
  'Generated by `tools/bundle.js` in https://github.com/ignisspindler/mindwright-experience-runtime. Do not edit these files; vendor a new bundle instead.',
  '',
  '- `core/index.js`: the portable MWER core (validate, compose, project). No platform dependencies.',
  '- `catalog.json` / `catalog.js`: the runtime catalog every core function takes as data.',
  '- `MANIFEST.json`: versions, source commit and a SHA-256 for every other file.',
  '',
  'Code in `core/` is MIT (`LICENSES/MIT.txt`). The catalog content is CC BY-NC-SA 4.0 (`LICENSES/CC-BY-NC-SA-4.0.txt`).',
  '',
].join('\n'));

const sha256 = content => `sha256:${createHash('sha256').update(content).digest('hex')}`;
const manifest = {
  name: 'mwer-browser',
  version,
  runtime: RUNTIME_VERSION,
  composer: COMPOSER_VERSION,
  commit,
  source: 'https://github.com/ignisspindler/mindwright-experience-runtime',
  files: Object.fromEntries([...files].sort(([a], [b]) => a.localeCompare(b)).map(([path, content]) => [path, sha256(content)])),
};

const out = resolve(values.out);
rmSync(out, { recursive: true, force: true });
for (const [path, content] of files) {
  mkdirSync(dirname(join(out, path)), { recursive: true });
  writeFileSync(join(out, path), content);
}
writeFileSync(join(out, 'MANIFEST.json'), `${JSON.stringify(manifest, null, 2)}\n`);
console.log(`Bundled mwer-browser ${version} (runtime ${RUNTIME_VERSION}, composer ${COMPOSER_VERSION}) into ${out}`);
